package com.fireplatform;

import com.fasterxml.jackson.databind.*;
import com.fireplatform.simcard.*;
import com.fireplatform.shared.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class SimCardInputsTest {
    final ObjectMapper json=new ObjectMapper().setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).enable(DeserializationFeature.USE_BIG_INTEGER_FOR_INTS).enable(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);
    final SimCardInputs inputs=new SimCardInputs(json);
    static final String PASSWORD="Synthetic-Confirm-Password";
    Map<String,Object> body(boolean edit){var body=new LinkedHashMap<String,Object>();body.put(edit?"expected_revision":"iccid",edit?0L:"000123Case");body.put("carrier_name","");body.put("replaceability","UNKNOWN");body.put("management_party","UNKNOWN");body.put("fee_responsibility","UNKNOWN");body.put("reported_operator_status","UNKNOWN");body.put("expires_on",null);body.put("evidence_at",null);body.put("source_note","");return body;}
    byte[] raw(String value){return value.getBytes(StandardCharsets.UTF_8);}
    SimCardInputs.Metadata parse(Map<String,Object> body,boolean edit)throws Exception{return inputs.metadata(json.writeValueAsBytes(body),edit);}
    void bad(org.assertj.core.api.ThrowableAssert.ThrowingCallable code){assertThatThrownBy(code).isInstanceOfSatisfying(ApiError.class,e->{assertThat(e.status).isEqualTo(400);assertThat(e.code).isEqualTo("INVALID_REQUEST");assertThat(e.getMessage()).doesNotContain("SECRET");});}
    @Test void onlyDatesAreNullableAndAllTenKeysAreRequired()throws Exception{for(boolean edit:List.of(false,true)){var body=body(edit);assertThat(body).hasSize(9);assertThat(parse(body,edit).expiresOn()).isNull();assertThat(parse(body,edit).evidenceAt()).isNull();for(String key:new ArrayList<>(body.keySet())){var missing=new LinkedHashMap<>(body);missing.remove(key);bad(()->parse(missing,edit));if(!Set.of("expires_on","evidence_at").contains(key)){var nil=new LinkedHashMap<>(body);nil.put(key,null);bad(()->parse(nil,edit));}}}}
    @Test void iccidIsOpaqueCanonicalTextNotNumberOrProviderValidation(){assertThat(SimCardInputs.iccid("  000a/中  ")).isEqualTo("000a/中");assertThat(SimCardInputs.iccid("Ａ１２")).isEqualTo("Ａ１２");assertThat(SimCardInputs.iccid("Case")).isNotEqualTo(SimCardInputs.iccid("case"));assertThat(SimCardInputs.iccid("\u00a0x\u00a0")).isEqualTo("\u00a0x\u00a0");}
    @Test void controlsAreRejectedBeforeJavaTrimAndUnicodeIsNeverRepaired(){for(String value:Arrays.asList(null,""," ","\ticcid","iccid\n","\u007ficcid","\u0085iccid","\u0000iccid","\uD800"))bad(()->SimCardInputs.iccid(value));for(String value:List.of("\ncarrier","carrier\t","\uD800"))bad(()->SimCardInputs.carrier(value));}
    @Test void textLimitsAreCentralUtf16UnitsAndOnlyEdgeJavaTrimApplies(){assertThat(SimCardInputs.iccid("😀".repeat(32))).hasSize(Limits.SIM_CARD_ICCID_MAX);bad(()->SimCardInputs.iccid("😀".repeat(33)));assertThat(SimCardInputs.carrier("😀".repeat(100))).hasSize(Limits.SIM_CARD_CARRIER_MAX);bad(()->SimCardInputs.carrier("😀".repeat(101)));assertThat(SimCardInputs.note("😀".repeat(500))).hasSize(Limits.SIM_CARD_SOURCE_NOTE_MAX);bad(()->SimCardInputs.note("😀".repeat(501)));}
    @Test void sourceNoteIsRequiredStringWithInternalCrLfTabAndEmptyUnknown(){assertThat(SimCardInputs.note(" \r\n\t ")).isEmpty();assertThat(SimCardInputs.note("  a\r\n\tb  ")).isEqualTo("a\r\n\tb");for(String value:Arrays.asList(null,"\u0000","\u000b","\u0085","\uD800"))bad(()->SimCardInputs.note(value));}
    @Test void requestScalarsNeverCoerceOrPopulateFixedOrScopeFields()throws Exception{for(Object value:List.of(1,true,List.of("x"),Map.of("x","y"))){var body=body(false);body.put("carrier_name",value);bad(()->parse(body,false));}for(String key:List.of("tenant_id","id","installation_form","information_source","actor_user_id","recorded_at","revision","device_id","last_sync_at")){var body=body(false);body.put(key,"SECRET");bad(()->parse(body,false));}}
    @Test void createAndEditShapesAreDistinctAndIccidCannotBeEdited()throws Exception{var create=body(false);create.put("expected_revision",0);bad(()->parse(create,false));var edit=body(true);edit.put("iccid","same");bad(()->parse(edit,true));bad(()->parse(body(false),true));}
    @Test void duplicateTrailingRootArrayAndNullRequestsFail()throws Exception{String valid=json.writeValueAsString(body(false));for(String value:List.of("null","[]","{}",valid+" {}",valid.substring(0,valid.length()-1)+",\"iccid\":\"SECRET\"}"))bad(()->inputs.metadata(raw(value),false));}
    @Test void expectedRevisionRejectsStringsDecimalsExponentsNegativeAndNearIntegers()throws Exception{String valid=json.writeValueAsString(body(true));for(String value:List.of("\"0\"","0.0","0e0","0.00000000000000000000001","-1","9007199254740992","9223372036854775808","true","null"))bad(()->inputs.metadata(raw(valid.replace("\"expected_revision\":0","\"expected_revision\":"+value)),true));assertThat(parse(body(true),true).expectedRevision()).isZero();var maximum=body(true);maximum.put("expected_revision",SimCardInputs.MAX_SAFE);assertThat(parse(maximum,true).expectedRevision()).isEqualTo(SimCardInputs.MAX_SAFE);}
    @Test void rawNegativeZeroRevisionMustNotLoseItsSignInTheJsonTree()throws Exception{String valid=json.writeValueAsString(body(true));bad(()->inputs.metadata(raw(valid.replace("\"expected_revision\":0","\"expected_revision\":-0")),true));}
    @Test void enumsAreExplicitIndependentClosedAndNeverTrimmed()throws Exception{for(String key:List.of("replaceability","management_party","fee_responsibility","reported_operator_status"))for(String value:List.of("unknown"," UNKNOWN ","SECRET","")){var body=body(false);body.put(key,value);bad(()->parse(body,false));}var body=body(false);body.put("replaceability","NOT_REPLACEABLE");body.put("management_party","MANUFACTURER");body.put("fee_responsibility","TENANT");body.put("reported_operator_status","ACTIVE");var value=parse(body,false);assertThat(value.replaceability()).isEqualTo("NOT_REPLACEABLE");assertThat(value.feeResponsibility()).isEqualTo("TENANT");}
    @Test void expiryIsGregorianDateNotInstantOrGuessedEndOfDay(){for(String value:List.of("0001-01-01","2000-02-29","9999-12-31"))assertThat(SimCardInputs.date(value)).isEqualTo(value);assertThat(SimCardInputs.date(null)).isNull();for(String value:List.of("","0000-01-01","10000-01-01","1900-02-29","2026-02-30","2026-1-01","2026-01-01T00:00:00Z"," 2026-01-01","２０２６-01-01"))bad(()->SimCardInputs.date(value));}
    @Test void evidenceUtcMicrosecondsCanonicalizeWithoutMillisecondRoundTrip(){assertThat(SimCardInputs.evidence("2026-01-02T03:04:05.1Z")).isEqualTo("2026-01-02T03:04:05.100000Z");assertThat(SimCardInputs.evidence("2026-01-02T03:04:05.123456Z")).endsWith(".123456Z");assertThat(SimCardInputs.evidence("0001-01-01T00:00:00Z")).isEqualTo("0001-01-01T00:00:00.000000Z");assertThat(SimCardInputs.evidence(null)).isNull();}
    @Test void evidenceRejectsOffsetEpochMissingSecondsExcessPrecisionAndInvalidDates(){for(String value:List.of("2026-01-01T00:00Z","2026-01-01T00:00:00+00:00","2026-01-01T00:00:00","2026-01-01T00:00:00.1234567Z","2026-01-01T24:00:00Z","2026-01-01T00:00:60Z","1900-02-29T00:00:00Z","0000-01-01T00:00:00Z","1760000000","","2026-01-01T00:00:00z"))bad(()->SimCardInputs.evidence(value));}
    @Test void noUnapprovedExpiryOrEvidenceAgeOrFutureRuleIsIntroduced(){assertThat(SimCardInputs.date("0001-01-01")).isEqualTo("0001-01-01");assertThat(SimCardInputs.evidence("9999-12-31T23:59:59.999999Z")).isEqualTo("9999-12-31T23:59:59.999999Z");}
    @Test void actorConfirmationPasswordFieldIsRejected()throws Exception{var body=body(false);body.put("actor_password","Synthetic-Confirm-Password");bad(()->parse(body,false));}
    @Test void filterEscapesOnlyLiteralCardFieldsAndPageGrammarIsBounded(){var sql=SimCardFilter.parse(" %_! ").cards("tenant-a");assertThat(sql.where()).contains("c.tenant_id=?","LOWER(c.iccid)","LOWER(c.carrier_name)","LOWER(c.source_note)").doesNotContain("app_users","devices","products");assertThat(sql.arguments()).containsExactly("tenant-a","%!%!_!!%","%!%!_!!%","%!%!_!!%");for(String value:List.of("01","-1","1.0","1e0","2147483648",""))bad(()->SimCardFilter.number(value,1));}
}
